def lei(n: int) -> str: return f"TA1337{n:012d}00"
def figi(n: int) -> str: return f"BBG{n:08d}7"
class Store:
    def __init__(self, conn: psycopg.Connection) -> None: self.conn = conn
    def mint(self, kind: str, scheme: str, value: str, *, at: datetime = T0, birth_alias: bool = True) -> str:
        row = self.conn.execute( "select staging.entity_mint(%s, %s, %s, 'test:1337')::text", (kind, scheme, value) ).fetchone(); assert row is not None
        if birth_alias: self.alias(row[0], scheme, value, at=at)
        return str(row[0])
    def alias( self, entity_id: str, scheme: str, value: str, *, at: datetime = T0, confidence: str = "1", valid_from: str = "-infinity", valid_to: str | None = None, ) -> int: row = self.conn.execute( "\n            insert into staging.entity_aliases\n                (entity_id, scheme, value, valid_from, valid_to, transaction_time, source, raw_ref,\n                 method, confidence, mapping_version)\n            values (%s::uuid, %s, %s, %s::date, %s::date, %s, 'test:1337', 'test:1337',\n                    'asserted', %s::numeric, 'test:1337')\n            returning alias_id\n            ", (entity_id, scheme, value, valid_from, valid_to, at, confidence), ).fetchone(); assert row is not None; return int(row[0])
    def relate(self, relation_type: str, source: str, target: str, *, at: datetime = T0) -> str: method = "merge" if relation_type == "superseded_by" else "asserted"; row = self.conn.execute( "\n            insert into staging.entity_relations\n                (relation_id, relation_type, from_entity_id, to_entity_id, valid_from, transaction_time,\n                 source, raw_ref, method, confidence, mapping_version)\n            values (staging.entity_relation_uuid(%(type)s, %(source)s::uuid, %(target)s::uuid,\n                                                 '-infinity'::date, %(at)s, 'test:1337', %(method)s),\n                    %(type)s, %(source)s::uuid, %(target)s::uuid, '-infinity', %(at)s,\n                    'test:1337', 'test:1337', %(method)s, 1, 'test:1337')\n            returning relation_id::text\n            ", {"type": relation_type, "source": source, "target": target, "at": at, "method": method}, ).fetchone(); assert row is not None; return str(row[0])
    def end_alias(self, alias_id: int, valid_to: str, *, at: datetime) -> None: self.conn.execute( "\n            insert into staging.entity_retractions (alias_id, valid_to, reason, transaction_time, source, raw_ref)\n            values (%s, %s::date, 'test:1337', %s, 'test:1337', 'test:1337')\n            ", (alias_id, valid_to, at), )
    def retract_relation(self, relation_id: str, *, at: datetime) -> None: self.conn.execute( "\n            insert into staging.entity_retractions (relation_id, valid_to, reason, transaction_time, source, raw_ref)\n            values (%s::uuid, '2026-01-01', 'test:1337', %s, 'test:1337', 'test:1337')\n            ", (relation_id, at), )
    def kg(self, kg_id: str, display_name: str) -> None: self.conn.execute( "insert into staging.kg_entities (id, entity_type, display_name) values (%s, 'company', %s)", (kg_id, display_name), )
